def strategy(history, rng):
    if not history:
        return 'D'
    n = len(history)
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    oc = opp.count('C')
    od = n - oc
    mc = my.count('C')
    md = n - mc

    if n < 5:
        return 'D' if od > oc else 'C'

    last = opp[-1]
    last2 = opp[-2] if n >= 2 else last
    last3 = opp[-3] if n >= 3 else last2

    if n >= 8:
        def_score = sum(3 if my[i]=='C' and opp[i]=='C' else
                        0 if my[i]=='C' and opp[i]=='D' else
                        5 if my[i]=='D' and opp[i]=='C' else 1
                        for i in range(n-8, n))
    else:
        def_score = None

    # Detect always-defect: high opponent D rate recently, few C's ever
    recent_opp = opp[-10:] if n >= 10 else opp
    roc = recent_opp.count('C')
    rod = len(recent_opp) - roc

    if n >= 6 and rod >= len(recent_opp) - 1 and oc <= 1:
        return 'D'

    if n >= 4:
        opp_rate = oc / n
    else:
        opp_rate = 0.5

    # Tit-for-tat with forgiveness for sudden defection
    if last == 'D':
        # If very few defections overall, forgive occasionally
        if od <= 2 and n >= 6:
            if rng.random() < 0.6:
                return 'C'
        # If opponent alternates D C D C, defect back
        if n >= 4 and opp[-4:] == ['D','C','D','C']:
            return 'D'
        # If our last was C and they defected, likely exploit - retaliate
        if my[-1] == 'C':
            return 'D'
        # If we defected and they still defected, maybe pause? otherwise defect
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # last == 'C'
    if n >= 3 and opp[-3:] == ['D','D','C']:
        return 'D'
    if od >= 4 and n >= 8 and oc > 0:
        # Mostly defector, punish more
        if od > oc * 2:
            return 'D'
    if n >= 10:
        recent3 = opp[-3:].count('D')
        if recent3 == 3:
            return 'D'
        recent2 = opp[-2:].count('D')
        if recent2 == 2 and rng.random() < 0.5:
            return 'D'
    # Exploit heavy cooperators late
    if n > 50 and opp_rate > 0.75:
        return 'D'
    return 'C'

